-- Esquema de Marín 376 para Supabase (generado desde D1). Ejecutar en el SQL Editor del proyecto.
create schema if not exists marin376;
set search_path = marin376;

CREATE TABLE IF NOT EXISTS productos(sku TEXT PRIMARY KEY, id_loyverse TEXT, variant_id TEXT, nombre TEXT, categoria TEXT, costo DOUBLE PRECISION, precio DOUBLE PRECISION, stock DOUBLE PRECISION, track_stock INT, barcode TEXT, sold_by_weight INT, updated_at TEXT, fecha_creacion TEXT, descripcion TEXT, imagen_url TEXT, proveedor_id INT, sector TEXT);
CREATE TABLE IF NOT EXISTS proveedores (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS auditoria (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TEXT, accion TEXT, sku TEXT, producto TEXT, categoria TEXT, id_loyverse TEXT, stock DOUBLE PRECISION, motivo TEXT, responsable TEXT, cantidad DOUBLE PRECISION, vencimientos_id BIGINT);
CREATE TABLE IF NOT EXISTS carritos_guardados ("provId" TEXT PRIMARY KEY, "provLabel" TEXT, items TEXT NOT NULL, total DOUBLE PRECISION, fecha TEXT);
CREATE TABLE IF NOT EXISTS categoria_meta (categoria TEXT PRIMARY KEY, grupo_costo TEXT CHECK (grupo_costo IN ('COMPRAS','RRHH','OPERACIONAL','ADMINISTRATIVO','MARKETING','IMPUESTOS','FINANCIERO','OTRO')), seccion TEXT CHECK (seccion IN ('PERECIBLE','NO_PERECIBLE')), categoria_loyverse TEXT);
CREATE TABLE IF NOT EXISTS categorias_loyverse (id TEXT PRIMARY KEY, nombre TEXT);
CREATE TABLE IF NOT EXISTS clasificacion_abc (sku TEXT PRIMARY KEY, venta_total DOUBLE PRECISION, pct_participacion DOUBLE PRECISION, pct_acumulado DOUBLE PRECISION, clase TEXT, periodo_dias BIGINT, calculado_en TEXT);
CREATE TABLE IF NOT EXISTS clasificacion_pendiente (sku TEXT PRIMARY KEY REFERENCES productos(sku), motivo TEXT NOT NULL, fecha TEXT DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS config (clave TEXT PRIMARY KEY, valor TEXT);
CREATE TABLE IF NOT EXISTS config_costeo (id BIGINT PRIMARY KEY CHECK (id = 1), costo_fijo_default DOUBLE PRECISION NOT NULL DEFAULT 0, actualizado_en TEXT, exhib_watts DOUBLE PRECISION, exhib_kwh DOUBLE PRECISION, exhib_unidades_mes DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS config_costeo_producto (sku TEXT PRIMARY KEY, materia DOUBLE PRECISION, unidades DOUBLE PRECISION, minutos DOUBLE PRECISION, sueldo DOUBLE PRECISION, envase DOUBLE PRECISION, actualizado_en TEXT);
CREATE TABLE IF NOT EXISTS config_fiados (clave TEXT PRIMARY KEY, valor TEXT);
CREATE TABLE IF NOT EXISTS config_multiplo_producto (sku TEXT PRIMARY KEY, multiplo BIGINT NOT NULL, actualizado_en TEXT, empaque BIGINT, palabra TEXT);
CREATE TABLE IF NOT EXISTS config_vida_util (categoria TEXT PRIMARY KEY, dias_alerta BIGINT NOT NULL, tipo TEXT NOT NULL CHECK(tipo IN ('corta','larga','cambio')), nota TEXT);
CREATE TABLE IF NOT EXISTS configuracion (clave TEXT PRIMARY KEY, valor TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS control_dedup (clave TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS control_procesados (archivo TEXT PRIMARY KEY, procesado_en TEXT NOT NULL DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS control_tx (ym TEXT PRIMARY KEY, n_transacciones BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS diccionario_aprendido (patron TEXT PRIMARY KEY, tipo TEXT NOT NULL, categoria TEXT NOT NULL, nombre TEXT NOT NULL, aprendido_en TEXT NOT NULL DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS facturas_calculos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, factura_id TEXT NOT NULL, fecha TEXT NOT NULL, producto TEXT NOT NULL, costo_unitario DOUBLE PRECISION, margen DOUBLE PRECISION, precio_venta DOUBLE PRECISION, precio_psicologico DOUBLE PRECISION, categoria TEXT, responsable TEXT);
CREATE TABLE IF NOT EXISTS favoritos (sku TEXT PRIMARY KEY, fecha TEXT NOT NULL, responsable TEXT);
CREATE TABLE IF NOT EXISTS fiados (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cliente_id TEXT, receipt_id_loyverse TEXT NOT NULL UNIQUE, monto_total DOUBLE PRECISION NOT NULL, estado TEXT NOT NULL DEFAULT 'abierto', fecha_hora TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fiados_lineas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fiado_id BIGINT NOT NULL REFERENCES fiados(id), sku TEXT NOT NULL, producto_nombre TEXT, cantidad DOUBLE PRECISION NOT NULL, precio_unitario DOUBLE PRECISION NOT NULL, receipt_line_item_id TEXT);
CREATE TABLE IF NOT EXISTS fiados_refunds_linea_manual (receipt_refund_numero TEXT PRIMARY KEY, fiado_id BIGINT NOT NULL, creado TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS historial_precios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku TEXT NOT NULL, fecha TEXT NOT NULL, precio_antes DOUBLE PRECISION, precio_despues DOUBLE PRECISION, costo_antes DOUBLE PRECISION, costo_despues DOUBLE PRECISION, responsable TEXT);
CREATE TABLE IF NOT EXISTS llegadas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha_deteccion TEXT, sku TEXT NOT NULL, producto TEXT, categoria TEXT, stock_antes DOUBLE PRECISION, stock_despues DOUBLE PRECISION, aumento DOUBLE PRECISION, estado TEXT, fecha_vencimiento_asignada TEXT, fecha_resolucion TEXT);
CREATE TABLE IF NOT EXISTS logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TEXT DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'), mensaje TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mermas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TEXT, sku TEXT NOT NULL, producto TEXT, categoria TEXT, unidad TEXT, lote TEXT, cantidad DOUBLE PRECISION, costo_unitario DOUBLE PRECISION, costo_total DOUBLE PRECISION, motivo TEXT, estado_costo TEXT, responsable TEXT, origen TEXT);
CREATE TABLE IF NOT EXISTS movimientos_stock (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku TEXT NOT NULL, delta DOUBLE PRECISION NOT NULL, tipo TEXT NOT NULL, origen_id BIGINT, timestamp TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pagos_fiado (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cliente_id TEXT, fiado_id BIGINT NOT NULL REFERENCES fiados(id), monto DOUBLE PRECISION NOT NULL, fecha_hora TEXT NOT NULL, metodo_pago TEXT NOT NULL, receipt_id_loyverse_abono TEXT NOT NULL, receipt_line_item_id_abono TEXT);
CREATE TABLE IF NOT EXISTS pedidos_pendientes (sku TEXT PRIMARY KEY REFERENCES productos(sku), barcode TEXT, nombre TEXT, proveedor TEXT, cantidad BIGINT, canal TEXT, fecha TEXT DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'), costo_unitario DOUBLE PRECISION DEFAULT 0, costo_total DOUBLE PRECISION DEFAULT 0, fecha_llegada_estimada TEXT, estado TEXT DEFAULT 'confirmado');
CREATE TABLE IF NOT EXISTS por_revisar (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TEXT, n_operacion TEXT, descripcion TEXT NOT NULL, monto BIGINT NOT NULL, motivo TEXT, archivo TEXT, creado_en TEXT NOT NULL DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS prestamos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TEXT NOT NULL, sucursal TEXT NOT NULL, direccion TEXT NOT NULL, sku TEXT NOT NULL, producto TEXT, cantidad DOUBLE PRECISION NOT NULL, unidad TEXT, costo_unitario DOUBLE PRECISION, costo_total DOUBLE PRECISION, estado TEXT NOT NULL DEFAULT 'pendiente', fecha_devolucion TEXT, responsable TEXT, nota TEXT);
CREATE TABLE IF NOT EXISTS prestamos_dinero (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TEXT NOT NULL, sucursal TEXT NOT NULL, direccion TEXT NOT NULL, monto DOUBLE PRECISION NOT NULL, estado TEXT NOT NULL DEFAULT 'pendiente', fecha_cierre TEXT, responsable TEXT, nota TEXT);
CREATE TABLE IF NOT EXISTS prestamos_dinero_abonos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, prestamo_id BIGINT NOT NULL REFERENCES prestamos_dinero(id), fecha TEXT NOT NULL, monto DOUBLE PRECISION NOT NULL, responsable TEXT);
CREATE TABLE IF NOT EXISTS producto_clasificacion_aprendida (patron TEXT PRIMARY KEY, proveedor_id INT, sector TEXT);
CREATE TABLE IF NOT EXISTS producto_proveedor_id (sku TEXT NOT NULL, proveedor_id BIGINT NOT NULL REFERENCES proveedores(id), PRIMARY KEY (sku, proveedor_id));
CREATE TABLE IF NOT EXISTS producto_proveedores (sku TEXT NOT NULL, proveedor TEXT NOT NULL, PRIMARY KEY(sku, proveedor));
CREATE TABLE IF NOT EXISTS push_subscriptions (endpoint TEXT PRIMARY KEY, p256dh TEXT, auth TEXT, creado TEXT);
CREATE TABLE IF NOT EXISTS registros (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre TEXT NOT NULL, fecha TEXT NOT NULL, categoria TEXT NOT NULL, tipo TEXT NOT NULL CHECK (tipo IN ('INGRESO','COSTOS','GASTO OPE','MERMA','PLASTICOS','RETIRO_UTILIDAD','PRESTAMO','IMPUESTOS','INVERSION','TRASPASO_INTERNO')), cuenta TEXT NOT NULL CHECK (cuenta IN ('BANCO','EFECTIVO')), monto BIGINT NOT NULL, n_operacion TEXT NOT NULL UNIQUE, origen TEXT, subtipo_original TEXT, creado_en TEXT NOT NULL DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'), actualizado_en TEXT);
CREATE TABLE IF NOT EXISTS riesgo_excluidos (sku TEXT PRIMARY KEY, fecha TEXT NOT NULL, responsable TEXT);
CREATE TABLE IF NOT EXISTS sectores (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS sectores_personalizados (nombre TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS variant_map (variant_id TEXT PRIMARY KEY, sku TEXT NOT NULL REFERENCES productos(sku));
CREATE TABLE IF NOT EXISTS vencimientos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha_ingreso TEXT, sku TEXT NOT NULL, producto TEXT, categoria TEXT, unidad TEXT, lote TEXT, cantidad DOUBLE PRECISION, fecha_vencimiento TEXT, estado TEXT, prioridad TEXT, accion TEXT, precio_recomendado DOUBLE PRECISION, costo_usado DOUBLE PRECISION, costo_origen TEXT, fecha_revision TEXT, revisado_por TEXT, motivo_cierre TEXT, fecha_retiro TEXT, merma_id BIGINT, monto_descuento DOUBLE PRECISION, descuento_activo BIGINT DEFAULT 0, precio_original DOUBLE PRECISION, precio_aplicado DOUBLE PRECISION, cant_vendida_desc DOUBLE PRECISION DEFAULT 0, cant_merma_desc DOUBLE PRECISION DEFAULT 0, fecha_descuento_aplicado TEXT);
CREATE TABLE IF NOT EXISTS ventas_diarias (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha TEXT NOT NULL, sku TEXT NOT NULL, unidades DOUBLE PRECISION NOT NULL DEFAULT 0, venta DOUBLE PRECISION NOT NULL DEFAULT 0, utilidad DOUBLE PRECISION NOT NULL DEFAULT 0, UNIQUE(fecha, sku));
CREATE TABLE IF NOT EXISTS ventas_diarias_historico (fecha TEXT NOT NULL, sku TEXT NOT NULL, unidades DOUBLE PRECISION NOT NULL, venta BIGINT NOT NULL, utilidad BIGINT NOT NULL, PRIMARY KEY (fecha, sku));
CREATE TABLE IF NOT EXISTS ventas_recibos_detalle (receipt_number TEXT NOT NULL, sku TEXT NOT NULL, fecha TEXT NOT NULL, unidades DOUBLE PRECISION NOT NULL, venta DOUBLE PRECISION NOT NULL, utilidad DOUBLE PRECISION NOT NULL, PRIMARY KEY (receipt_number, sku));
CREATE INDEX IF NOT EXISTS idx_auditoria_fecha ON auditoria(fecha);
CREATE INDEX IF NOT EXISTS idx_auditoria_sku ON auditoria(sku);
CREATE INDEX IF NOT EXISTS idx_fiados_cliente ON fiados(cliente_id);
CREATE INDEX IF NOT EXISTS idx_fiados_estado ON fiados(estado);
CREATE INDEX IF NOT EXISTS idx_fiados_lineas_fiado ON fiados_lineas(fiado_id);
CREATE INDEX IF NOT EXISTS idx_historial_precios_sku ON historial_precios(sku);
CREATE INDEX IF NOT EXISTS idx_llegadas_estado ON llegadas(estado);
CREATE INDEX IF NOT EXISTS idx_llegadas_sku ON llegadas(sku);
CREATE INDEX IF NOT EXISTS idx_logs_fecha ON logs(fecha);
CREATE INDEX IF NOT EXISTS idx_mermas_fecha ON mermas(fecha);
CREATE INDEX IF NOT EXISTS idx_mermas_sku ON mermas(sku);
CREATE INDEX IF NOT EXISTS idx_movimientos_stock_sku ON movimientos_stock(sku);
CREATE INDEX IF NOT EXISTS idx_pagos_fiado_cliente ON pagos_fiado(cliente_id);
CREATE INDEX IF NOT EXISTS idx_pagos_fiado_fiado ON pagos_fiado(fiado_id);
CREATE INDEX IF NOT EXISTS idx_pedidos_pendientes_barcode ON pedidos_pendientes(barcode);
CREATE INDEX IF NOT EXISTS idx_porrevisar_fecha ON por_revisar(fecha);
CREATE INDEX IF NOT EXISTS idx_registros_categoria ON registros(categoria);
CREATE INDEX IF NOT EXISTS idx_registros_fecha ON registros(fecha);
CREATE INDEX IF NOT EXISTS idx_registros_tipo ON registros(tipo);
CREATE INDEX IF NOT EXISTS idx_vencimientos_estado ON vencimientos(estado);
CREATE INDEX IF NOT EXISTS idx_vencimientos_fecha_venc ON vencimientos(fecha_vencimiento);
CREATE INDEX IF NOT EXISTS idx_vencimientos_sku ON vencimientos(sku);
CREATE INDEX IF NOT EXISTS idx_ventas_fecha ON ventas_diarias(fecha);
CREATE INDEX IF NOT EXISTS idx_ventas_hist_sku_fecha ON ventas_diarias_historico(sku, fecha);
CREATE INDEX IF NOT EXISTS idx_ventas_sku_fecha ON ventas_diarias(sku, fecha);
CREATE OR REPLACE VIEW vw_ventas_resumen AS SELECT sku, SUM(unidades) AS u_all, SUM(CASE WHEN fecha >= to_char(('now')::date - 7,'YYYY-MM-DD') THEN unidades ELSE 0 END) AS u7, SUM(CASE WHEN fecha >= to_char(('now')::date - 14,'YYYY-MM-DD') THEN unidades ELSE 0 END) AS u14, SUM(CASE WHEN fecha >= to_char(('now')::date - 30,'YYYY-MM-DD') THEN unidades ELSE 0 END) AS u30, SUM(CASE WHEN fecha >= to_char(('now')::date - 90,'YYYY-MM-DD') THEN unidades ELSE 0 END) AS u90, SUM(venta) AS rev, SUM(utilidad) AS prof FROM ventas_diarias GROUP BY sku;
